// 📁 src/app/pages/home/home.component.ts

import { Component, OnInit, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { Observable, Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

// Importar desde la nueva arquitectura
import { Property } from '../../core/models/property.interface';
import { SearchParams } from '../../core/models/search.interface';
import { PropertyService } from '../../core/services/property.service';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit, OnDestroy {
  
  // 🎯 DATOS REACTIVOS desde servicios
  featuredProperties$: Observable<Property[]>;
  
  // 📊 Estado del componente
  isLoading = true;
  searchError: string | null = null;
  
  // 🔍 Datos del formulario de búsqueda
  searchData: SearchParams = {
    destination: '',
    checkIn: '',
    checkOut: '',
    guests: 2
  };
  
  // 🧹 Para cleanup de subscriptions
  private destroy$ = new Subject<void>();

  // 🏛️ Destinos disponibles para el selector
  readonly destinations = [
    { value: '', label: 'Selecciona tu destino en el Quindío' },
    { value: 'salento', label: 'Salento - Pueblo Patrimonio' },
    { value: 'valle-cocora', label: 'Valle de Cocora - Palmas de Cera' },
    { value: 'filandia', label: 'Filandia - Balcón del Quindío' },
    { value: 'armenia', label: 'Armenia - Ciudad Capital' },
    { value: 'calarca', label: 'Calarcá - Corazón del Eje Cafetero' },
    { value: 'montenegro', label: 'Montenegro - Ciudad Dulce' },
    { value: 'quimbaya', label: 'Quimbaya - Tradición Cafetera' },
    { value: 'circasia', label: 'Circasia - Pueblo Tranquilo' },
    { value: 'la-tebaida', label: 'La Tebaida - Puerta de Oro' },
    { value: 'buenavista', label: 'Buenavista - Paisajes Únicos' }
  ];

  // 📅 Fechas mínimas para los inputs
  readonly today = new Date().toISOString().split('T')[0];
  readonly tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];

  // 🚀 Sugerencias rápidas
  readonly quickSuggestions = [
    { destination: 'valle-cocora', label: 'Valle de Cocora', icon: '🏔️' },
    { destination: 'salento', label: 'Fincas Cafeteras', icon: '☕' },
    { destination: 'filandia', label: 'Pueblos Patrimonio', icon: '🏛️' },
    { destination: 'armenia', label: 'Experiencias Ecológicas', icon: '🌿' }
  ];

  // 🗺️ Destinos populares para cards
  readonly popularDestinations = [
    {
      key: 'salento',
      name: 'Salento',
      description: 'Pueblo patrimonio con arquitectura colonial, calle del recuerdo y puerta de entrada al Valle de Cocora.',
      image: 'https://images.unsplash.com/photo-1611273426858-450d8e3c9fce?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80'
    },
    {
      key: 'filandia',
      name: 'Filandia',
      description: 'El "Balcón del Quindío" ofrece las mejores vistas panorámicas de la región y arquitectura paisa auténtica.',
      image: 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80'
    },
    {
      key: 'armenia',
      name: 'Armenia',
      description: 'Capital del Quindío, centro urbano moderno con museos, parques temáticos y la mejor gastronomía de la región.',
      image: 'https://images.unsplash.com/photo-1577962917302-cd874c4e31d2?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80'
    }
  ];

  constructor(
    private propertyService: PropertyService,
    private router: Router
  ) {
    // 🔄 Inicializar observables
    this.featuredProperties$ = this.propertyService.getFeaturedProperties();
  }

  ngOnInit(): void {
    this.loadFeaturedProperties();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  /**
   * 🔄 Cargar propiedades destacadas
   */
  private loadFeaturedProperties(): void {
    this.isLoading = true;
    
    this.featuredProperties$
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (properties) => {
          this.isLoading = false;
          console.log('✅ Propiedades destacadas cargadas:', properties.length);
        },
        error: (error) => {
          this.isLoading = false;
          console.error('❌ Error cargando propiedades:', error);
        }
      });
  }

  /**
   * 🔍 Manejar envío del formulario de búsqueda
   */
  onSearchSubmit(form: any): void {
    if (form.valid) {
      this.onSearch(this.searchData);
    } else {
      this.searchError = 'Por favor completa todos los campos requeridos';
    }
  }

  /**
   * 🔍 Manejar búsqueda - VERSIÓN SIMPLIFICADA
   */
  onSearch(searchParams: SearchParams): void {
    // ✅ Validación básica
    if (!searchParams.destination) {
      this.searchError = 'Por favor selecciona un destino';
      return;
    }

    if (!searchParams.checkIn || !searchParams.checkOut) {
      this.searchError = 'Por favor selecciona las fechas de tu estadía';
      return;
    }

    // ✅ Limpiar errores
    this.searchError = null;

    // ✅ Navegar a resultados con parámetros
    this.router.navigate(['/search'], { 
      queryParams: {
        destination: searchParams.destination,
        checkIn: searchParams.checkIn,
        checkOut: searchParams.checkOut,
        guests: searchParams.guests
      }
    });

    // 📊 Analytics/tracking (opcional)
    console.log('🔍 Búsqueda realizada:', searchParams);
  }

  /**
   * 🏠 Ver detalles de una propiedad específica
   */
  viewPropertyDetails(propertyId: string): void {
    // 📊 Registrar visualización
    this.propertyService.incrementPropertyViews(propertyId)
      .pipe(takeUntil(this.destroy$))
      .subscribe();

    // 🧭 Navegar a detalles
    this.router.navigate(['/property', propertyId]);
  }

  /**
   * ❤️ Toggle favorito desde la página principal
   */
  toggleFavorite(propertyId: string, event: Event): void {
    event.stopPropagation(); // Evitar navegación
    
    this.propertyService.toggleFavorite(propertyId)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (isFavorite) => {
          console.log(`${isFavorite ? '❤️' : '🤍'} Propiedad ${propertyId}`);
        },
        error: (error) => {
          console.error('❌ Error al actualizar favorito:', error);
        }
      });
  }

  /**
   * 🚀 Acciones rápidas para sugerencias
   */
  searchDestination(destination: string): void {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    
    const dayAfter = new Date();
    dayAfter.setDate(dayAfter.getDate() + 3);

    const searchParams: SearchParams = {
      destination,
      checkIn: tomorrow.toISOString().split('T')[0],
      checkOut: dayAfter.toISOString().split('T')[0],
      guests: 2
    };

    this.onSearch(searchParams);
  }

  /**
   * 🏷️ Buscar por tipo de experiencia
   */
  searchByExperience(experience: string): void {
    this.router.navigate(['/search'], { 
      queryParams: {
        experience,
        guests: 2
      }
    });
  }

  /**
   * 🎯 Tracking de interacciones (para analytics)
   */
  trackInteraction(action: string, data?: any): void {
    console.log(`📊 Interaction: ${action}`, data);
    // Aquí implementarías Google Analytics, etc.
  }

  /**
   * 📝 TrackBy function para ngFor optimizado
   */
  trackByPropertyId(index: number, property: Property): string {
    return property.id;
  }

  /**
   * 🏷️ Obtener nombre amigable del tipo de propiedad
   */
  getPropertyTypeName(type: string): string {
    const types: { [key: string]: string } = {
      'finca': 'Finca Cafetera',
      'cabana': 'Cabaña Ecológica',
      'hacienda': 'Hacienda Tradicional',
      'glamping': 'Glamping'
    };
    return types[type] || type;
  }

  /**
   * 🗺️ Ver todas las propiedades
   */
  viewAllProperties(): void {
    this.router.navigate(['/search']);
  }
}
